---筛选界面
---@class UIScreenDialogs
---@field EventReceive                  	UnityEngine.RectTransform
---@field CommonUITitleNode             	UnityEngine.RectTransform
---@field BtnSure                       	UnityEngine.RectTransform
---@field BtnRest                       	UnityEngine.RectTransform
---@field BtnBack                       	UnityEngine.RectTransform
---@field Content                       	UnityEngine.RectTransform
---@field ScreenTypeNode                	UnityEngine.RectTransform
local UIScreenDialogs = Class("UIScreenDialogs")

--------------- import ---------------
local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
local UIModule = CS.Engine.UI.UIModule
local KTool = CS.Engine.Lib.KTool
local GameObject = CS.UnityEngine.GameObject
--------------- import ---------------

--------------- define ---------------
--local CardUtils = CardUtils
---@type CardConfMgr
local CardConfMgr = CardConfMgr:GetInstance()
--local UIFilterType =  Constants.UIFilterType
local CommonUITitleNode = "Game.UI.Common.CommonUITitleNode"
--------------- define ---------------

function UIScreenDialogs:__init()
    self.parameters = nil --- {
    --- datas = {}, groups = {} --可选的
    --- callBack = function(data, groups) --可选
    ---}

end

function UIScreenDialogs:__delete()
    self.controller = nil
    self.parameters = nil
    self.filterClass = nil
    self.extraParams = nil
end

function UIScreenDialogs:Awake()
    SetButtonAction(self.BtnSure.gameObject, Bind(self, self.OnClickBtnSureAction))
    SetButtonAction(self.BtnRest.gameObject, Bind(self, self.OnClickBtnRestAction))
    SetButtonAction(self.BtnBack.gameObject, Bind(self, self.OnClickBtnBackAction))
    SetButtonAction(self.EventReceive.gameObject, Bind(self, self.OnClickBtnBackAction))

    KTool.SetActive(self.Content.gameObject, false)
end


function UIScreenDialogs:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        --初始化参数
        ---@type Engine.UI.UIArgument
        local argument = self.controller.Argument
        self.parameters = argument.parameters
        self:RefreshTitle()
        --生成筛选类型
        self:CreateScreenType()
    end))
    return coWait
end

function UIScreenDialogs:OnShow()
    return CoWaitDo(function() 
        Events.Broadcast(Constants.EventNames.UIScreenDialogsShowState, true)
    end)
end

function UIScreenDialogs:RefreshTitle()
    local env = CfUtils.GetLuaScr(self.CommonUITitleNode, CommonUITitleNode)
    if env then
        env:Refresh(self.parameters.title or localize("筛选"))
    end
end

---CreateScreenType
---生成筛选类型
---
function UIScreenDialogs:CreateScreenType()
    local parent = self.ScreenTypeNode.gameObject
    local child = self.Content.gameObject
    --KTool.DestroyGameObjectChildren(parent)
    local screenList = CardConfMgr:GetAllScreenVo(self.parameters.filterClass)
    for i, v in pairs(screenList) do
        local go = parent.transform:Find(i)
        if not go then
            go = parent:AddChild(child)
        end
        go.name = i

        KTool.SetActive(go.gameObject, true)
        ---@type ScreenToggle
        local env = CfUtils.GetLuaScr(go, Constants.UILuaTablePath.UIScreenType)
        if not isNull(env) then
            env:FreshNode(v, self.parameters.groups)
        end
            --local uiScreenType = GetLuaBehaviour(go, Constants.UILuaTablePath.UIScreenType)
            --if not isNull(uiScreenType) then
            --    ---@type UIScreenType
            --    local env = uiScreenType.Env
            --    env:FreshNode(v, self.parameters.groups)
            --end
        -- end
    end
end

---OnScreenSureClick
---点击确认筛选按钮
---
function UIScreenDialogs:OnClickBtnSureAction()
    self:ScreenData(self.parameters.groups)
    self:CloseUI()
end

function UIScreenDialogs:OnClickBtnRestAction()
    if next(self.parameters.groups) == nil then return end
    self.isRest = true
    self.parameters.groups = self.parameters.defGroups and clone(self.parameters.defGroups) or {}
    GameUtils.Toast(localize("重置成功"))
    Events.Broadcast("EventUIScreenDialogsRest")
    self:CreateScreenType()
    --self:ScreenData(self.parameters.groups)
    --UIModule.BackDialog()
end

function UIScreenDialogs:ScreenData(groups)
    if not isNull(self.parameters.callBack) then
        self.parameters.callBack(groups)
    end
end

---OnScreenReturnClick
---取消筛选按钮
---
function UIScreenDialogs:OnClickBtnBackAction()
    if self.isRest then
        self:OnClickBtnSureAction()
    else
        self:CloseUI()
    end
end

function UIScreenDialogs:CloseUI()
    Events.Broadcast(Constants.EventNames.UIScreenDialogsShowState, false)
    self.controller:Close()
end


function UIScreenDialogs:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.parameters = nil
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIScreenDialogs